package io.github.classgraph.base.internal.utils;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;

import org.jspecify.annotations.Nullable;

/** A class storing accept or reject criteria. */
public abstract class AcceptReject {
    protected @Nullable Set<String> accept;
    protected @Nullable Set<String> reject;
    protected @Nullable Set<String> acceptPrefixesSet;
    protected @Nullable List<String> acceptPrefixes;
    protected @Nullable List<String> rejectPrefixes;
    protected @Nullable Set<String> acceptGlobs;
    protected @Nullable Set<String> rejectGlobs;
    protected @Nullable List<Pattern> acceptPatterns;
    protected @Nullable List<Pattern> acceptPrefixPatterns;
    protected @Nullable List<Pattern> rejectPatterns;
    protected char separatorChar;

    protected AcceptReject(final char separatorChar) {
        this.separatorChar = separatorChar;
    }

    /** Compatibility delegation for callers that still reference the pre-extraction API. */
    public static Pattern globToPattern(final String glob, final char separatorChar, final boolean prefixMatch) {
        return AcceptRejectUtils.globToPattern(glob, separatorChar, prefixMatch);
    }

    /** Compatibility delegation for callers that still reference the pre-extraction API. */
    public static String stripTrailingDoubleGlob(final String packageOrPath, final char separatorChar) {
        return AcceptRejectUtils.stripTrailingDoubleGlob(packageOrPath, separatorChar);
    }

    /** Compatibility delegation for callers that still reference the pre-extraction API. */
    public static boolean containsWildcard(final String str) {
        return AcceptRejectUtils.containsWildcard(str);
    }

    /** Compatibility delegation for callers that still reference the pre-extraction API. */
    public static String normalizePath(final String path) {
        return AcceptRejectUtils.normalizePath(path);
    }

    /** Compatibility delegation for callers that still reference the pre-extraction API. */
    public static String normalizePackageOrClassName(final String packageOrClassName) {
        return AcceptRejectUtils.normalizePackageOrClassName(packageOrClassName);
    }

    /** Compatibility delegation for callers that still reference the pre-extraction API. */
    public static String pathToPackageName(final String path) {
        return AcceptRejectUtils.pathToPackageName(path);
    }

    /** Compatibility delegation for callers that still reference the pre-extraction API. */
    public static String packageNameToPath(final String packageName) {
        return AcceptRejectUtils.packageNameToPath(packageName);
    }

    /** Compatibility delegation for callers that still reference the pre-extraction API. */
    public static String classNameToClassfilePath(final String className) {
        return AcceptRejectUtils.classNameToClassfilePath(className);
    }

    /** Compatibility delegation for callers that still reference the pre-extraction API. */
    public static boolean matchesPatternList(final String str, final @Nullable List<Pattern> patterns) {
        return AcceptRejectUtils.matchesPatternList(str, patterns);
    }

    /** Compatibility delegation for callers that still reference the pre-extraction API. */
    public static void quoteList(final Collection<String> coll, final StringBuilder buf) {
        AcceptRejectUtils.quoteList(coll, buf);
    }

    /** Compatibility adapter for the extracted top-level implementation. */
    public static class AcceptRejectPrefix extends io.github.classgraph.base.internal.utils.AcceptRejectPrefix {
        public AcceptRejectPrefix(final char separatorChar) {
            super(separatorChar);
        }
    }

    /** Compatibility adapter for the extracted top-level implementation. */
    public static class AcceptRejectWholeString
            extends io.github.classgraph.base.internal.utils.AcceptRejectWholeString {
        public AcceptRejectWholeString(final char separatorChar) {
            super(separatorChar);
        }
    }

    /** Compatibility adapter for the extracted top-level implementation. */
    public static class AcceptRejectLeafname extends io.github.classgraph.base.internal.utils.AcceptRejectLeafname {
        public AcceptRejectLeafname(final char separatorChar) {
            super(separatorChar);
        }
    }

    public abstract void addToAccept(String str);

    public abstract void addToReject(String str);

    public abstract boolean isAcceptedAndNotRejected(String str);

    public abstract boolean isAccepted(String str);

    public abstract boolean acceptHasPrefix(String str);

    public abstract boolean isRejected(String str);

    public boolean acceptIsEmpty() {
        return accept == null && acceptPrefixes == null && acceptPrefixesSet == null && acceptGlobs == null;
    }

    public boolean rejectIsEmpty() {
        return reject == null && rejectPrefixes == null && rejectGlobs == null;
    }

    public boolean acceptAndRejectAreEmpty() {
        return acceptIsEmpty() && rejectIsEmpty();
    }

    public boolean isSpecificallyAcceptedAndNotRejected(final String str) {
        return !acceptIsEmpty() && isAcceptedAndNotRejected(str);
    }

    public boolean isSpecificallyAccepted(final String str) {
        return !acceptIsEmpty() && isAccepted(str);
    }

    public void sortPrefixes() {
        if (acceptPrefixesSet != null) {
            acceptPrefixes = new ArrayList<>(acceptPrefixesSet);
        }
        if (acceptPrefixes != null) {
            CollectionUtils.sortIfNotEmpty(acceptPrefixes);
        }
        if (rejectPrefixes != null) {
            CollectionUtils.sortIfNotEmpty(rejectPrefixes);
        }
    }

    @Override
    public String toString() {
        final StringBuilder buf = new StringBuilder();
        if (accept != null) {
            buf.append("accept: ");
            AcceptRejectUtils.quoteList(accept, buf);
        }
        if (acceptPrefixes != null) {
            if (!buf.isEmpty())
                buf.append("; ");
            buf.append("acceptPrefixes: ");
            AcceptRejectUtils.quoteList(acceptPrefixes, buf);
        }
        if (acceptGlobs != null) {
            if (!buf.isEmpty())
                buf.append("; ");
            buf.append("acceptGlobs: ");
            AcceptRejectUtils.quoteList(acceptGlobs, buf);
        }
        if (reject != null) {
            if (!buf.isEmpty())
                buf.append("; ");
            buf.append("reject: ");
            AcceptRejectUtils.quoteList(reject, buf);
        }
        if (rejectPrefixes != null) {
            if (!buf.isEmpty())
                buf.append("; ");
            buf.append("rejectPrefixes: ");
            AcceptRejectUtils.quoteList(rejectPrefixes, buf);
        }
        if (rejectGlobs != null) {
            if (!buf.isEmpty())
                buf.append("; ");
            buf.append("rejectGlobs: ");
            AcceptRejectUtils.quoteList(rejectGlobs, buf);
        }
        return buf.toString();
    }
}
